{
  "steps": [
    {
      "action": "Inventory the binary's format, architecture, entrypoints, sections, imports, exports, symbols, strings, and protections to establish the analysis prerequisites for input-validation recovery.",
      "technique": "RE-BINARY-INVENTORY",
      "deterministic_check": "The analyzed artifact hash matches campaign metadata; binary format and architecture are recorded; expected inventory artifacts (sections, imports, exports, symbols, strings) exist and parse successfully; any missing or malformed inputs are reported as incomplete rather than absence."
    },
    {
      "action": "Map static call relationships around the input surface, identifying entrypoints, callers, callees, indirect-call uncertainty, and data-flow-relevant helpers that participate in input handling.",
      "technique": "RE-STATIC-CALLGRAPH",
      "deterministic_check": "Every claimed call edge has an address or symbol locator; unresolved indirect calls are listed explicitly; the call graph identifies which paths are proven and which remain candidates."
    },
    {
      "action": "Trace input acquisition through parsing, transformations, comparisons, branch decisions, success paths, and rejection paths to recover the validation logic, then document accepted input by deterministically replaying recorded inputs against the recovered decision points.",
      "technique": "RE-INPUT-VALIDATION-TRACE",
      "deterministic_check": "The input source and destination representation are identified; every success and rejection branch has a code locator; transformations and comparison constants are supported by decompilation or disassembly evidence; unknown helper behavior is represented as an unresolved dependency; accepted input is documented from replay-validated branch outcomes."
    }
  ]
}
